const fs = require('fs');
const path = require('path');

const logPath = 'C:\\Users\\user\\.gemini\\antigravity\\brain\\6d259fa0-fa10-467d-8539-aaa3c2a69afb\\.system_generated\\logs\\transcript_full.jsonl';
const content = fs.readFileSync(logPath, 'utf8');
const lines = content.split('\n');

let count = 0;
for (const line of lines) {
  if (line.includes('GET /api/listings 200') || line.includes('"status":200') || line.includes('listings":[')) {
    console.log(`Line ${count} matches!`);
    fs.writeFileSync(`backend/scratch/match_${count}.json`, line);
    count++;
  }
}
console.log(`Done. Found ${count} matching lines.`);
